/** The earliest start day in fromDay..toDay (both included) with the lowest quoted total for a hire with no pets. */
export function cheapestStart(boatClass: BoatClass, nights: number, fromDay: number, toDay: number): number {
    let bestDay = fromDay;
    let bestTotal = Infinity;
    for (let day = fromDay; day <= toDay; day++) {
        const { totalPence } = quoteHire({ boatClass, startDay: day, nights, pets: 0 });
        if (totalPence < bestTotal) {
            bestTotal = totalPence;
            bestDay = day;
        }
    }
    return bestDay;
}
